    fun timeMonthDay(day: Int, month: Int): UiMessage = UiMessage("time.month_day", mapOf("day" to day, "month" to month))
    fun timeMonthGroup(month: Int): UiMessage = UiMessage("time.month_group", mapOf("month" to month))
    fun timeToday(): UiMessage = UiMessage("time.today", emptyMap())
    fun timeWeekday(day: String): UiMessage = UiMessage("time.weekday", mapOf("day" to day))
    fun timeYearMonthGroup(month: Int, year: Int): UiMessage = UiMessage("time.year_month_group", mapOf("month" to month, "year" to year))
    fun timeYesterday(): UiMessage = UiMessage("time.yesterday", emptyMap())
}

object MessageLocale {
    val appleTags = mapOf("zh-CN" to "zh-Hans", "en" to "en")
    private val languages = mapOf("zh" to "zh-CN", "en" to "en")
    fun resolve(preference: String = "auto", system: List<String> = listOf(java.util.Locale.getDefault().toLanguageTag())): String {
        if (preference in appleTags) return preference
        for (tag in system) {
            val base = tag.replace('_', '-').lowercase(java.util.Locale.ROOT).substringBefore('.').substringBefore('@').substringBefore('-')
            languages[base]?.let { return it }
        }
        return "zh-CN"
    }
}
